      example: '-- 查看所有表空间\nSELECT tablespace_name, status FROM dba_tablespaces;\n-- 查看数据文件与大小\nSELECT file_name, tablespace_name, bytes/1024/1024 MB FROM dba_data_files;\n-- 表空间使用率\nSELECT d.tablespace_name, ROUND(d.bytes/1024/1024) total_mb,\n       ROUND((d.bytes-NVL(f.bytes,0))/1024/1024) used_mb\n  FROM dba_data_files d\n  LEFT JOIN (SELECT file_id, SUM(bytes) bytes FROM dba_free_space GROUP BY file_id) f ON d.file_id=f.file_id;',
      tips: '默认表空间:SYSTEM、SYSAUX、USERS、UNDOTBS1、TEMP。',
