      example: 'CREATE TABLE t_type (\n  id        NUMBER(10)     PRIMARY KEY,\n  name      VARCHAR2(50)   NOT NULL,\n  salary    NUMBER(10,2)   DEFAULT 0,\n  hire_date DATE           DEFAULT SYSDATE,\n  bio       CLOB,\n  photo     BLOB\n);',
